import{_ as h,B as i,o,c as m,a8 as n,d as c,w as d,f as t,E as r,af as p,a}from"./chunks/framework.CNIpabDg.js";const S=JSON.parse(`{"title":"Browser storage","description":"Understand Xila's browser disk cache, multi-disk OPFS management, and durability boundaries.","frontmatter":{"layout":"doc","docType":"explanation","description":"Understand Xila's browser disk cache, multi-disk OPFS management, and durability boundaries."},"headers":[],"relativePath":"explanation/browser-storage.md","filePath":"explanation/browser-storage.md","lastUpdated":1793145952000}`),u={name:"explanation/browser-storage.md"};function g(b,e,w,f,v,y){const l=i("Mermaid"),s=i("CodeReference");return o(),m("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[6]||(e[6]=n('<h1 id="browser-storage" tabindex="-1">Browser storage <a class="header-anchor" href="#browser-storage" aria-label="Permalink to &quot;Browser storage&quot;">​</a></h1><p>The browser example keeps Xila filesystems in origin-private OPFS images. Its design bridges synchronous block-device operations and asynchronous browser storage while preserving existing disks on startup errors.</p><h2 id="disks-and-their-origin" tabindex="-1">Disks and their origin <a class="header-anchor" href="#disks-and-their-origin" aria-label="Permalink to &quot;Disks and their origin&quot;">​</a></h2><p>Each browser disk is a 16 MiB MBR/LittleFS image stored on the current origin. The legacy image is named <code>xila_drive.img</code>. New images created from the Help panel use <code>xila_YYYY-MM-DD.img</code>, with a numeric suffix when more than one image is created on the same date. The selected disk is remembered for the origin.</p><p>Files, configuration, and credentials survive reloads when the browser keeps the corresponding OPFS image. Another origin has separate storage, even when it serves the same application. <strong>The demonstration moved from Core Pages to <a href="https://platforms.xila.dev/" target="_blank" rel="noreferrer">platforms.xila.dev</a>; browsers do not transfer old-origin disks to the new site automatically.</strong></p><p>A new image is initialized from a prebuilt, locale-matched LittleFS seed containing the bundled applications and shortcut metadata. Updating Xila or its reference seed does <strong>not</strong> silently replace applications already installed in an existing image; create another disk if you need the newer bundle while keeping the old disk as a backup.</p><p>On a fresh image, startup creates the default administrator account with an empty password. On an existing image, it restores users and groups, including when the administrator was removed. Invalid partition tables or filesystem mount errors stop boot without reformatting the saved image. Changing the requested disk size does not silently resize an existing image.</p><h2 id="why-there-is-a-memory-cache" tabindex="-1">Why there is a memory cache <a class="header-anchor" href="#why-there-is-a-memory-cache" aria-label="Permalink to &quot;Why there is a memory cache&quot;">​</a></h2><p>Synchronous OPFS handles are available only in workers, while this example&#39;s UI and filesystem operate on the browser main thread. The drive therefore serves synchronous block operations from a bounded, disk-sized memory cache and commits snapshots asynchronously through <code>DriveDevice::sync().await</code>.</p><p>Synchronous filesystem flushes update this cache, not OPFS. A completed asynchronous sync establishes that a snapshot was committed and reports storage errors to the caller.</p>',10)),(o(),c(p,null,{default:d(()=>[r(l,{id:"mermaid-30",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20VFS%5BMBR%20%2F%20LittleFS%20operations%5D%20--%3E%20Cache%5BMain-thread%20memory%20cache%5D%0A%20%20%20%20Cache%20--%3E%7Cdirty%20snapshot%7C%20Save%5BSerialized%20asynchronous%20save%5D%0A%20%20%20%20Save%20--%3E%20OPFS%5BSelected%20origin-private%20image%5D%0A%20%20%20%20Lock%5BPer-disk%20lifetime%20Web%20Lock%5D%20--%3E%20OPFS%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=n('<h2 id="ownership-switching-and-removal" tabindex="-1">Ownership, switching, and removal <a class="header-anchor" href="#ownership-switching-and-removal" aria-label="Permalink to &quot;Ownership, switching, and removal&quot;">​</a></h2><p>A lifetime Web Lock gives one Xila tab access to a particular disk. Another tab cannot open that same image until the first releases it. Different tabs may use different Xila images on the same origin.</p><p>The Help panel lists managed images, creates new ones, selects a different image, and removes unused images. Switching disks first stops new writes, commits pending changes, releases the current disk lock, then reloads Xila with the selected image. If the save or switch fails, the runtime keeps the current image selected rather than silently abandoning it.</p><p>The active disk cannot be removed from its own tab. Removal also acquires the target disk&#39;s lock, so an image opened by another tab is rejected. Deletion is permanent for that image and requires confirmation in the browser UI.</p><h2 id="autosave-and-memory-cost" tabindex="-1">Autosave and memory cost <a class="header-anchor" href="#autosave-and-memory-cost" aria-label="Permalink to &quot;Autosave and memory cost&quot;">​</a></h2><p>The example saves at boot, every second when dirty, and on normal shutdown. Clean disks are not rewritten. Saves are serialized and atomic, with one additional disk-sized snapshot rather than an unbounded queue. Autosave failures are logged and retried; unsaved changes remain available in the cache.</p><p>For the selected 16 MiB image, the example uses a 16 MiB cache and temporarily needs another 16 MiB snapshot while saving, plus browser buffering. Bundled guest bytes, VFS copies, the interpreter, guest memory, and graphical resources add further costs. Additional stored disk images consume persistent OPFS quota but are not all cached in RAM at once.</p><h2 id="durability-boundaries" tabindex="-1">Durability boundaries <a class="header-anchor" href="#durability-boundaries" aria-label="Permalink to &quot;Durability boundaries&quot;">​</a></h2><p>Abrupt reloads, tab closure, and crashes can lose changes since the last successful save. Background-tab timer throttling can extend that interval. OPFS is browser-managed: quota limits, private browsing, eviction, or clearing site data can remove images. It is not a replacement for backups.</p><p>Disk removal is an explicit user action; a mount failure does not grant startup permission to erase an image. The <a href="/how-to/reset-browser-storage.html">browser disk procedure</a> explains how to create, switch, and deliberately remove images.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2>',11)),a("ul",null,[e[3]||(e[3]=a("li",null,[a("a",{href:"/reference/wasm-runtime.html#browser-capabilities"},"Browser capabilities"),t(".")],-1)),e[4]||(e[4]=a("li",null,[a("a",{href:"./architecture/drivers/wasm.html"},"WASM drive integration"),t(".")],-1)),e[5]||(e[5]=a("li",null,[a("a",{href:"/how-to/validate-core.html#browser-behavior"},"Browser validation"),t(".")],-1)),a("li",null,[r(s,{repo:"platforms",path:"drivers/wasm/src/devices/drive.rs"}),e[1]||(e[1]=t(" and ",-1)),r(s,{repo:"platforms",path:"examples/wasm/src/storage.rs"}),e[2]||(e[2]=t(".",-1))])])])}const x=h(u,[["render",g]]);export{S as __pageData,x as default};
